--
-- Name: vista_carga_estudiantes; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.vista_carga_estudiantes AS
 WITH asignaturas_consolidadas AS (
         SELECT TRIM(BOTH FROM asignaturas.codigo_asignatura) AS codigo_asignatura,
            TRIM(BOTH FROM asignaturas.grupo) AS grupo,
            string_agg(DISTINCT NULLIF(TRIM(BOTH FROM asignaturas.nombre_completo), ''::text), ' / '::text) AS profesor,
            string_agg(DISTINCT NULLIF(TRIM(BOTH FROM asignaturas.correo_institucional), ''::text), ' / '::text) AS correo_profesor,
            max((asignaturas.id_semestre)::text) AS id_semestre
           FROM public.asignaturas
          GROUP BY (TRIM(BOTH FROM asignaturas.codigo_asignatura)), (TRIM(BOTH FROM asignaturas.grupo))
        )
 SELECT e.codigo_est,
    jsonb_build_object('codigo_est', e.codigo_est, 'primer_nombre', max(TRIM(BOTH FROM e.primer_nombre)), 'primer_apellido', max(TRIM(BOTH FROM e.primer_apellido)), 'nombre_programa', max(TRIM(BOTH FROM e.nombre_programa)), 'codigo_sede', max(e.codigo_sede), 'nombre_sede', max(TRIM(BOTH FROM e.nombre_sede)), 'grupo', max(TRIM(BOTH FROM e.grupo)), 'asignaturas', jsonb_agg(jsonb_build_object('codigo_asignatura', TRIM(BOTH FROM e.codigo_asignatura), 'nombre_asignatura', TRIM(BOTH FROM e.nombre_asignatura), 'grupo', TRIM(BOTH FROM e.grupo), 'profesor', COALESCE(ac.profesor, 'Docente Titular UIS'::text), 'correo_profesor', COALESCE(ac.correo_profesor, 'Coordinación IPRED'::text), 'id_semestre', ac.id_semestre))) AS perfil_academico
   FROM (public.estudiantes e
     LEFT JOIN asignaturas_consolidadas ac ON (((TRIM(BOTH FROM e.codigo_asignatura) = ac.codigo_asignatura) AND (TRIM(BOTH FROM e.grupo) = ac.grupo))))
  GROUP BY e.codigo_est
  WITH NO DATA;


